SET = 2
Q1 = READ(1, "निम्नलिखित गद्यांश को पढ़कर उस पर आधारित पूछे गए प्रश्नों के उत्तर लिखिए:",
 "<p>जल जीवन का आधार है। पृथ्वी का तीन-चौथाई भाग जल से घिरा है, फिर भी पीने योग्य जल की मात्रा बहुत कम है। बढ़ती जनसंख्या, उद्योगों के रासायनिक कचरे और खेती में अंधाधुंध पानी के उपयोग ने जल-संकट को गहरा दिया है। राजस्थान जैसे प्रदेशों में तो महिलाओं को मटके भरने के लिए कई किलोमीटर चलना पड़ता है। हमारे पूर्वजों ने बावड़ियों, तालाबों और कुंडों के रूप में वर्षा-जल को सहेजने की सुंदर परंपरा विकसित की थी, किंतु आधुनिक सुविधाओं की चकाचौंध में हम उन्हें भूलते गए। आज नलों से बहता पानी हमें अनंत लगता है, इसलिए हम उसे बेहिसाब बहने देते हैं। यदि हम ब्रश करते समय नल बंद रखें, छत के वर्षा-जल का संग्रह करें और रिसते नलों की मरम्मत कराएँ, तो प्रतिदिन हज़ारों लीटर पानी बचाया जा सकता है। जल-संरक्षण केवल सरकार का नहीं, प्रत्येक नागरिक का कर्तव्य है। यदि आज हमने बूँद-बूँद की क़ीमत न समझी, तो आने वाली पीढ़ियों को प्यासा रहना पड़ेगा।</p>",
 [sub(M("गद्यांश के अनुसार जल-संकट गहराने का कारण नहीं है —", ["बढ़ती जनसंख्या", "उद्योगों का रासायनिक कचरा", "वर्षा-जल का संग्रह", "खेती में अधिक पानी का उपयोग"], 2), 1, "वर्षा-जल संग्रह तो समाधान है, कारण नहीं।"),
  sub(AR("पृथ्वी के तीन-चौथाई भाग पर जल होते हुए भी जल-संकट है।", "पृथ्वी पर पीने योग्य जल की मात्रा बहुत कम है।", 2), 1),
  sub(ST("निम्नलिखित में से जल-बचत के उपायों के रूप में गद्यांश में आए कथनों का चयन कीजिए:", ["ब्रश करते समय नल बंद रखना", "छत के वर्षा-जल का संग्रह करना", "रिसते नलों की मरम्मत न कराना", "नलों का पानी खुला छोड़ देना"], (0, 1)), 1),
  sub(dict(q="हमारे पूर्वजों ने वर्षा-जल को सहेजने के लिए क्या किया था? हम उसे क्यों भूलते गए?", kind="s", ans="उत्तर-बिंदु", sol="पूर्वजों ने बावड़ियों, तालाबों और कुंडों का निर्माण किया (1); आधुनिक सुविधाओं की चकाचौंध और नलों से बहते पानी को अनंत मान लेने के कारण हम उन्हें भूलते गए (1)।"), 2),
  sub(dict(q="‘बूँद-बूँद की क़ीमत’ समझने से लेखक का क्या तात्पर्य है? अपने शब्दों में लिखिए।", kind="s", ans="उत्तर-बिंदु", sol="जल की प्रत्येक बूँद को अमूल्य मानकर उसे व्यर्थ न करना (1); भावी पीढ़ियों के लिए जल बचाने की ज़िम्मेदारी निभाना (1)।"), 2)])
Q2 = READ(2, "निम्नलिखित काव्यांश को ध्यानपूर्वक पढ़कर उस पर आधारित पूछे गए प्रश्नों के उत्तर लिखिए:",
 "दीपक जलता रहा रात भर,<br>आँधियों ने बहुत डराया।<br>छोटी-सी लौ ने मुस्काकर<br>अँधियारे को राह दिखाया।<br>न वह सूरज, न वह चंदा,<br>फिर भी उसने कर्म निभाया।<br>जितना तेल, जितनी बाती,<br>उतना पथ उजियार बनाया।<br>सीख यही कि छोटे से भी<br>बड़े काम हो जाते हैं,<br>बस जलने का साहस चाहिए,<br>तम खुद ही छँट जाते हैं।",
 [sub(M("‘दीपक’ किसका प्रतीक है?", ["साधन-संपन्न बड़े व्यक्ति का", "सीमित साधनों में भी कर्तव्य निभाने वाले साहसी व्यक्ति का", "अहंकारी व्यक्ति का", "भयभीत व्यक्ति का"], 1), 1),
  sub(ST("काव्यांश के आधार पर सही कथनों का चयन कीजिए:", ["दीपक आँधियों से भयभीत होकर बुझ गया।", "दीपक सूरज या चंदा न होकर भी अपना कर्म निभाता रहा।", "दीपक ने अपने सामर्थ्य जितना उजाला किया।", "अँधेरा दीपक से डरकर और बढ़ गया।"], (1, 2)), 1),
  sub(AR("कवि के अनुसार छोटे साधनों से भी बड़े काम हो सकते हैं।", "साहस और संकल्प हो तो अँधेरा स्वयं छँट जाता है।", 2), 1),
  sub(dict(q="‘बस जलने का साहस चाहिए’ पंक्ति में कवि क्या संदेश देना चाहता है?", kind="s", ans="उत्तर-बिंदु", sol="सफलता के लिए साधनों से अधिक साहस और संकल्प चाहिए (1); बिना हिचक अपना कर्म करने वाला व्यक्ति कठिनाइयों को दूर कर लेता है (1)।"), 2),
  sub(dict(q="‘न वह सूरज, न वह चंदा’ से कवि ने दीपक की किस स्थिति की ओर संकेत किया है?", kind="s", ans="उत्तर-बिंदु", sol="दीपक सूरज-चंदा की तरह विशाल नहीं, अत्यंत साधारण है (1); फिर भी वह अपने हिस्से का उजाला अवश्य करता है (1)।"), 2)])
