  sub(ST("गद्यांश के आधार पर सही कथनों का चयन कीजिए:", ["मूर्ति का चश्मा रोज़ एक-सा रहता था।", "कैप्टन ग्राहक की माँग पर मूर्ति का फ्रेम बदल देता था।", "कैप्टन की इस तत्परता में देश-प्रेम निहित था।", "लोग हर रोज़ चश्मा बदलने वाले को पहचानते थे।"], (1, 2)), 1),
  sub(AR("कैप्टन मूर्ति पर नया फ्रेम लगा देता था।", "वह नेताजी की मूर्ति को बिना चश्मे के नहीं देख सकता था।", 2), 1),
  sub(M("‘मौन प्रेम’ से तात्पर्य है —", ["प्रेम जो बिना शब्दों के कर्म में प्रकट हो", "चुप रहने की आदत", "गुप्त षड्यंत्र", "संकोच"], 0), 1),
