  sub(AR("गोपियों ने योग-ज्ञान को ‘कड़वी ककड़ी’ कहा।", "वह उनकी प्रेम-भावना के सर्वथा प्रतिकूल था।", 2), 1),
  sub(M("‘हारिल की लकड़ी’ किस भाव की प्रतीक है?", ["अटूट प्रेम और दृढ़ निष्ठा", "आलस्य", "भय", "क्रोध"], 0), 1),
